const PLAYBACK_MEDIA_FIXTURE_BASE64 = {
  mp4: "",
  mp3: "",
  ogg: "",
  m4a: "",
  flac: "",
  webm: "",
} as const;

export type PlaybackMediaFixtureFormat = keyof typeof PLAYBACK_MEDIA_FIXTURE_BASE64;

export function createPlaybackMediaFixture(format: PlaybackMediaFixtureFormat): Buffer {
  return Buffer.from(PLAYBACK_MEDIA_FIXTURE_BASE64[format], "base64");
}
